B.bhX=new A.bt([0,"\u0916\u094d\u092f\u093e\u0924\u094b\u093d\u091f\u0928\u094b\u093d\u0932\u094d\u092a\u0927\u0928\u0927\u093e\u0928\u094d\u092f\u0938\u0941\u0924\u0903 \u092a\u094d\u0930\u0924\u093e\u092a\u0940 \u0936\u0942\u0930\u0936\u094d\u091a \u092e\u0947\u0937\u0917\u0924\u092d\u093e\u0928\u094c",1,"\u0935\u0938\u094d\u0924\u094d\u0930\u0917\u0928\u094d\u0927\u094b\u092a\u091c\u0940\u0935\u0940 \u0938\u094d\u0924\u094d\u0930\u0940\u0926\u094d\u0935\u0947\u0937\u0940 \u0917\u0940\u0924\u0935\u093e\u0926\u094d\u092f\u0928\u093f\u092a\u0941\u0923\u094b \u0935\u0943\u0937\u092d\u0947",2,"\u0935\u094d\u092f\u093e\u0915\u0930\u0923\u091c\u094d\u091e\u094b \u0926\u0948\u0935\u091c\u094d\u091e\u094b \u0927\u0928\u0940 \u092e\u093f\u0925\u0941\u0928\u0947 \u092d\u093e\u0928\u094c",3,"\u0938\u0947\u0935\u093e\u0935\u0943\u0924\u094d\u0924\u093f\u0930\u094d\u0926\u0930\u093f\u0926\u094d\u0930\u0903 \u0915\u094d\u0930\u0942\u0930\u0936\u094d\u091a\u0928\u094d\u0926\u094d\u0930\u0930\u094d\u0915\u094d\u0937\u0947 \u0930\u0935\u094c",4,"\u0935\u0928\u091a\u0930\u094b \u092c\u0932\u0935\u093e\u0928\u094d \u092e\u0942\u0930\u094d\u0916\u094b \u092d\u093e\u0928\u094c \u0938\u093f\u0902\u0939\u0917\u0924\u0947",5,"\u0938\u094d\u0924\u094d\u0930\u0948\u0923\u094b \u092f\u0928\u094d\u0924\u094d\u0930\u091c\u094d\u091e\u094b \u0935\u093f\u0937\u092d\u0940\u0924\u093f\u0903 \u0915\u0928\u094d\u092f\u093e\u0917\u0924\u0947 \u092d\u093e\u0928\u094c",6,"\u0938\u0941\u0930\u093e\u0935\u093f\u0915\u094d\u0930\u092f\u0940 \u092a\u0923\u094d\u092f\u091c\u0940\u0935\u0940 \u092a\u0930\u0938\u094d\u0924\u094d\u0930\u0940\u0930\u0924\u094b \u0928\u0940\u091a\u0938\u094d\u0924\u0941\u0932\u093e\u0917\u0924\u0947",7,"\u0926\u0941\u0903\u0916\u0940 \u0935\u093f\u092e\u093e\u0928\u093f\u0924\u094b \u092c\u0926\u094d\u0927\u094b \u0935\u0943\u0936\u094d\u091a\u093f\u0915\u0947 \u0930\u0935\u094c",8,"\u0927\u0928\u0935\u093e\u0928\u094d \u092e\u0928\u094d\u0924\u094d\u0930\u0935\u093f\u0924\u094d \u0938\u092a\u0941\u0924\u094d\u0930\u094b \u0927\u0928\u094d\u0935\u0940\u0936\u0947 \u092d\u093e\u0928\u094c",9,"\u0927\u0928\u0928\u093e\u0936\u094b \u092a\u093f\u0924\u0943\u0935\u093f\u092f\u094b\u0917\u094b \u092e\u0915\u0930\u0947 \u092d\u093e\u0928\u094c",10,"\u0928\u0940\u091a\u0903 \u0938\u0941\u0924\u092d\u093e\u0917\u094d\u092f\u092a\u0930\u093f\u091a\u094d\u092f\u0941\u0924\u094b\u093d\u0938\u094d\u0935\u094b \u0918\u091f\u0947",11,"\u0924\u094b\u092f\u094b\u0924\u094d\u0925\u092a\u0923\u094d\u092f\u0935\u093f\u092d\u0935\u094b \u0935\u0928\u093f\u0924\u093e\u0926\u0943\u0924\u094b\u093d\u0928\u094d\u0924\u094d\u092f\u0947"],t.TM)
B.bhS=new A.bt([0,"\u0905\u0932\u094d\u092a\u0927\u0928\u094b \u0935\u093f\u0915\u0932\u0936\u094d\u091a\u092a\u0932\u094b \u092e\u0947\u0937\u0947 \u0936\u0936\u093f\u0928\u093f",1,"\u0938\u0941\u092d\u0917\u094b \u0927\u0928\u0935\u093e\u0928\u094d \u092d\u094b\u0917\u0940 \u0935\u0943\u0937\u092d\u0947 \u0936\u0936\u093f\u0928\u093f",2,"\u0935\u093f\u0926\u094d\u0935\u093e\u0928\u094d \u0915\u0932\u093e\u092a\u094d\u0930\u093f\u092f\u094b \u0930\u0938\u093f\u0915\u094b \u092e\u093f\u0925\u0941\u0928\u0947 \u091a\u0928\u094d\u0926\u094d\u0930\u0947",3,"\u0938\u094d\u0925\u093f\u0930\u092e\u0928\u093e\u0903 \u0917\u0943\u0939\u0938\u0941\u0916\u0940 \u091c\u0932\u092a\u094d\u0930\u0940\u0924\u093f\u0903 \u0915\u0930\u094d\u0915\u091f\u0947 \u091a\u0928\u094d\u0926\u094d\u0930\u0947",4,"\u0909\u0926\u093e\u0930\u0903 \u0915\u094d\u0930\u094b\u0927\u0940 \u0935\u0928\u092a\u094d\u0930\u093f\u092f\u0903 \u0938\u093f\u0902\u0939\u0947 \u0936\u0936\u093f\u0928\u093f",5,"\u0935\u093f\u0928\u092f\u0940 \u092a\u0930\u0938\u0947\u0935\u0915\u0903 \u0915\u0928\u094d\u092f\u093e\u092f\u093e\u0902 \u091a\u0928\u094d\u0926\u094d\u0930\u0947",6,"\u0915\u093e\u092e\u0941\u0915\u094b \u0930\u0942\u092a\u0935\u093e\u0928\u094d \u0935\u0923\u093f\u0915\u094d \u0924\u0941\u0932\u093e\u092f\u093e\u0902 \u091a\u0928\u094d\u0926\u094d\u0930\u0947",7,"\u0908\u0930\u094d\u0937\u094d\u092f\u093e\u0932\u0941\u0903 \u0915\u0932\u0939\u092a\u094d\u0930\u093f\u092f\u094b \u0935\u0943\u0936\u094d\u091a\u093f\u0915\u0947 \u0936\u0936\u093f\u0928\u093f",8,"\u0938\u093e\u0939\u0938\u0940 \u0927\u0940\u0930\u094b \u092f\u093e\u0924\u094d\u0930\u093e\u092a\u094d\u0930\u093f\u092f\u094b \u0927\u0928\u0941\u0937\u093f \u091a\u0928\u094d\u0926\u094d\u0930\u0947",9,"\u0915\u0937\u094d\u091f\u0936\u0940\u0932\u094b \u0915\u0943\u0937\u093f\u0915\u093e\u0930\u094b \u092e\u0915\u0930\u0947 \u0936\u0936\u093f\u0928\u093f",10,"\u092a\u093e\u092a\u0940 \u092e\u0926\u094d\u092f\u092a\u094b \u0938\u094d\u0924\u094d\u0930\u0940\u0932\u094b\u0932\u0903 \u0915\u0941\u092e\u094d\u092d\u0947 \u091a\u0928\u094d\u0926\u094d\u0930\u0947",11,"\u0930\u0942\u092a\u0935\u093e\u0928\u094d \u0927\u093e\u0930\u094d\u092e\u093f\u0915\u094b \u0935\u093f\u0926\u094d\u0935\u093e\u0928\u094d \u0938\u0941\u0916\u0940 \u092e\u0940\u0928\u0947 \u0936\u0936\u093f\u0928\u093f"],t.TM)
